DDL = '''
CREATE TABLE IF NOT EXISTS sources (
    fonte_id    INTEGER PRIMARY KEY AUTOINCREMENT,
    nome        TEXT NOT NULL UNIQUE,
    tipo        TEXT NOT NULL CHECK(tipo IN ('influencer','bolao','site','outro')),
    canal       TEXT,
    url         TEXT,
    ativo       INTEGER DEFAULT 1,
    criado_em   TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS tips (
    tip_id            INTEGER PRIMARY KEY AUTOINCREMENT,
    concurso          INTEGER NOT NULL,
    numero_jogo       INTEGER NOT NULL,
    fonte_id          INTEGER NOT NULL REFERENCES sources(fonte_id),
    voto              TEXT NOT NULL CHECK(voto IN ('1','X','2')),
    confianca         REAL DEFAULT 0.7 CHECK(confianca BETWEEN 0.0 AND 1.0),
    timestamp_palpite TEXT DEFAULT (datetime('now')),
    observacao        TEXT,
    acertou           INTEGER CHECK(acertou IN (0,1,NULL)),
    peso_atual        REAL DEFAULT 1.0,
    UNIQUE(concurso, numero_jogo, fonte_id)
);

CREATE TABLE IF NOT EXISTS model_scores (
    score_id        INTEGER PRIMARY KEY AUTOINCREMENT,
    concurso        INTEGER NOT NULL,
    numero_jogo     INTEGER NOT NULL,
    score_0_100     REAL,
    prob_1          REAL,
    prob_x          REAL,
    prob_2          REAL,
    consenso_massa  REAL,
    divergencia     REAL,
    valor_esperado  REAL,
    metodo          TEXT DEFAULT 'poisson_calibrado_v2',
    calculado_em    TEXT DEFAULT (datetime('now')),
    UNIQUE(concurso, numero_jogo)
);

CREATE INDEX IF NOT EXISTS idx_tips_concurso  ON tips(concurso, numero_jogo);
CREATE INDEX IF NOT EXISTS idx_tips_fonte      ON tips(fonte_id);
CREATE INDEX IF NOT EXISTS idx_scores_concurso ON model_scores(concurso);
'''


# ── funcoes ───────────────────────────────────────────────────────────────

def _db_path_real():
    candidatos = [
        DB_PATH,
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "loteca_historico.db"),
        os.path.join(os.getcwd(), "loteca_historico.db"),
        "/opt/render/project/src/loteca_historico.db",
    ]
    for p in candidatos:
        if os.path.exists(p): return p
    return DB_PATH


def aplicar_schema(conn):
    conn.executescript(DDL)
    conn.commit()
    print("Tabelas criadas (ou ja existiam)")


def popular_sources(conn):
    c = conn.cursor(); ins = 0
    for s in SOURCES_INICIAIS:
        c.execute("INSERT OR IGNORE INTO sources(nome,tipo,canal,url) VALUES(?,?,?,?)",
                  (s["nome"], s["tipo"], s["canal"], s["url"]))
        if c.rowcount: ins += 1
    conn.commit()
    print("Sources: %d inseridas, %d ja existiam" % (ins, len(SOURCES_INICIAIS)-ins))


def prob_historica_jogo(concurso, numero_jogo, conn):
    c = conn.cursor()
    c.execute("SELECT mandante, visitante FROM jogos WHERE concurso=? AND (sequencial=? OR numero_jogo=?)",
              (concurso, numero_jogo, numero_jogo))
    row = c.fetchone()
    if not row:
        pos = str(numero_jogo) if str(numero_jogo) in PROB_POR_POSICAO else "1"
        p = PROB_POR_POSICAO.get(pos, [DIST_GLOBAL["p1"], DIST_GLOBAL["px"], DIST_GLOBAL["p2"]])
        return {"p1": p[0], "px": p[1], "p2": p[2], "fonte": "posicao_fallback"}
    mandante, visitante = row
    # H2H direto
    for h in H2H_HISTORICO:
        if h["mandante"] == mandante and h["visitante"] == visitante:
            return {"p1": h["p1"], "px": h["px"], "p2": h["p2"], "fonte": "h2h_%dx" % h["total"]}
    # Gols reais
    gc = GOLS_CASA.get(mandante)
    gf = GOLS_FORA.get(visitante)
    if gc and gf:
        lc = max(0.3, min(gc["gm"] * (gf["gc"] / max(0.5, LAMBDA_FORA)) * 1.10, 5.0))
        lf = max(0.3, min(gf["gm"] * (gc["gc"] / max(0.5, LAMBDA_CASA)) * 0.90, 5.0))
        import math
        def pp(lam, k):
            return (lam**k) * math.exp(-lam) / math.factorial(k) if lam > 0 else (1.0 if k==0 else 0.0)
        p1 = px = p2 = 0.0
        for i in range(8):
            for j in range(8):
                p = pp(lc,i) * pp(lf,j)
                if i>j: p1+=p
                elif i==j: px+=p
                else: p2+=p
        t = p1+px+p2
        if t > 0:
            return {"p1":round(p1/t,4),"px":round(px/t,4),"p2":round(p2/t,4),"fonte":"poisson_gols","lc":round(lc,3),"lf":round(lf,3)}
    # Aproveitamento historico
    tc = TIMES_CASA.get(mandante)
    tf = TIMES_FORA.get(visitante)
    if tc and tf:
        raw_p1 = tc["aprov"] * 0.6 + (1 - tf["aprov"]) * 0.4
        raw_p2 = tf["aprov"] * 0.6 + (1 - tc["aprov"]) * 0.4
        raw_px = max(0.1, 1.0 - raw_p1 - raw_p2)
        total  = raw_p1 + raw_px + raw_p2
        return {"p1":round(raw_p1/total,4),"px":round(raw_px/total,4),"p2":round(raw_p2/total,4),"fonte":"aproveitamento"}
    # Fallback por posicao
    pos = str(numero_jogo) if str(numero_jogo) in PROB_POR_POSICAO else "1"
    p = PROB_POR_POSICAO.get(pos, [DIST_GLOBAL["p1"], DIST_GLOBAL["px"], DIST_GLOBAL["p2"]])
    return {"p1": p[0], "px": p[1], "p2": p[2], "fonte": "posicao"}


def score_jogo(prob):
    return round(prob["p1"] * 100 + prob["px"] * 50, 2)


def calcular_consenso(conn, concurso, numero_jogo):
    c = conn.cursor()
    c.execute("SELECT t.voto, t.confianca, t.peso_atual FROM tips t WHERE t.concurso=? AND t.numero_jogo=?",
              (concurso, numero_jogo))
    rows = c.fetchall()
    if not rows: return {"consenso": None, "n_fontes": 0, "votos": {}}
    mapa = {"1": 100.0, "X": 50.0, "2": 0.0}
    total_peso = soma = 0.0
    votos = {"1": 0, "X": 0, "2": 0}
    for voto, conf, peso in rows:
        w = conf * peso
        soma += mapa[voto] * w
        total_peso += w
        votos[voto] += 1
    return {"consenso": round(soma/total_peso,2) if total_peso else 50.0,
            "n_fontes": len(rows), "votos": votos, "peso_total": round(total_peso,4)}


def calcular_e_salvar_score(conn, concurso, numero_jogo):
    prob    = prob_historica_jogo(concurso, numero_jogo, conn)
    score   = score_jogo(prob)
    cons    = calcular_consenso(conn, concurso, numero_jogo)
    consenso = cons["consenso"] if cons["consenso"] is not None else score
    div     = round(score - consenso, 2)
    p_max   = max(prob["p1"], prob["px"], prob["p2"])
    ve      = round(div * p_max, 2)
    conn.execute(
        "INSERT OR REPLACE INTO model_scores"
        " (concurso, numero_jogo, score_0_100, prob_1, prob_x, prob_2, consenso_massa, divergencia, valor_esperado)"
        " VALUES (?,?,?,?,?,?,?,?,?)",
        (concurso, numero_jogo, score, prob["p1"], prob["px"], prob["p2"], consenso, div, ve))
    conn.commit()
    return {"score": score, "prob": prob, "divergencia": div, "valor_esperado": ve}


def fechar_rodada(conn, concurso):
    c = conn.cursor()
    c.execute("SELECT sequencial, resultado FROM jogos WHERE concurso=? AND resultado IN ('1','X','2')", (concurso,))
    resultados = dict(c.fetchall())
    if not resultados:
        c.execute("SELECT numero_jogo, resultado FROM jogos WHERE concurso=? AND resultado IN ('1','X','2')", (concurso,))
        resultados = dict(c.fetchall())
    if not resultados: print("Concurso %d sem resultados" % concurso); return
    atualizados = 0
    for num_jogo, resultado in resultados.items():
        c.execute("UPDATE tips SET acertou=CASE WHEN voto=? THEN 1 ELSE 0 END"
                  " WHERE concurso=? AND numero_jogo=? AND acertou IS NULL",
                  (resultado, concurso, num_jogo))
        atualizados += c.rowcount
    conn.commit()
    print("%d tips avaliados para concurso %d" % (atualizados, concurso))
    _atualizar_pesos(conn, concurso)


def _atualizar_pesos(conn, concurso):
    c = conn.cursor()
    c.execute("SELECT t.tip_id, t.voto, t.acertou, t.peso_atual, t.numero_jogo"
              " FROM tips t WHERE t.concurso=? AND t.acertou IS NOT NULL", (concurso,))
    tips = c.fetchall()
    contagem = defaultdict(lambda: defaultdict(int))
    for _, voto, _, _, num_jogo in tips:
        contagem[num_jogo][voto] += 1
    voto_massa = {j: max(v, key=v.get) for j, v in contagem.items()}
    for tip_id, voto, acertou, peso, num_jogo in tips:
        massa = voto_massa.get(num_jogo)
        diff  = (voto != massa) if massa else False
        if acertou:
            fator = FATOR_ACERTO_DIFERENCIAL if diff else FATOR_ACERTO_COMUM
        else:
            fator = FATOR_ERRO_DIFERENCIAL if not diff else FATOR_ERRO_COMUM
        novo = round(min(PESO_MAX, max(PESO_MIN, peso * fator)), 4)
        c.execute("UPDATE tips SET peso_atual=? WHERE tip_id=?", (novo, tip_id))
    conn.commit()
    print("Pesos atualizados: %d tips do concurso %d" % (len(tips), concurso))


def resumo_fontes(conn):
    c = conn.cursor()
    c.execute("SELECT s.fonte_id, s.nome, s.tipo, COUNT(t.tip_id),"
              " SUM(CASE WHEN t.acertou=1 THEN 1 ELSE 0 END), AVG(t.peso_atual)"
              " FROM sources s LEFT JOIN tips t ON s.fonte_id=t.fonte_id"
              " GROUP BY s.fonte_id ORDER BY AVG(t.peso_atual) DESC")
    cols = ["fonte_id","nome","tipo","total_tips","acertos","peso_medio"]
    return [dict(zip(cols, row)) for row in c.fetchall()]


